package com.example.rokidgeminisecretary;
import org.json.*;import java.io.*;
final class AttentionHub {
 static JSONObject row(String type,String id,String title,String reason,String route)throws Exception{return new JSONObject().put("type",type).put("id",id).put("title",title).put("reason",reason).put("route",route);}
 static JSONObject read(MainActivity c)throws Exception{JSONArray items=new JSONArray(),issues=new JSONArray();try{JSONArray jobs=CancellableWork.list(c);for(int i=0;i<jobs.length();i++){JSONObject job=jobs.getJSONObject(i);if(job.optString("phase").matches("FAILED|UNCONFIRMED_AFTER_RESTART|START_UNCONFIRMED|STOP_REQUESTED"))items.put(row("job",job.optString("id"),"長い処理の結果を確認",job.optString("kind")+" / "+job.optString("phase"),"jobs"));}}catch(Exception e){issues.put("処理状態");}try{JSONArray tasks=MeetingTaskBoard.list(c);java.time.LocalDate today=java.time.LocalDate.now();for(int i=0;i<tasks.length();i++){JSONObject task=tasks.getJSONObject(i);if(task.optString("state").equals("pending")&&!task.optString("due").isEmpty()&&java.time.LocalDate.parse(task.getString("due")).isBefore(today))items.put(row("task",task.getString("id"),task.getString("title"),"期限を過ぎています："+task.getString("due"),"tasks"));}}catch(Exception e){issues.put("タスクの期限");}try{JSONArray memory=MemoryProvenance.list(c);for(int i=0;i<memory.length();i++){JSONObject row=memory.getJSONObject(i),meta=row.optJSONObject("provenance");if(meta!=null&&(meta.optBoolean("reviewDue")||!meta.optBoolean("matchesContent")))items.put(row("memory",row.getString("id"),row.optString("topic"),meta.optBoolean("reviewDue")?"記憶の見直し日です":"本文と出典の対応を再確認してください","memory"));}}catch(Exception e){issues.put("記憶の見直し");}try{JSONArray inbox=SecretaryInbox.list(c).getJSONArray("items");for(int i=0;i<inbox.length();i++){JSONObject item=inbox.getJSONObject(i);if(item.optString("state").matches("unknown|failed|executing"))items.put(row("inbox",item.getString("id"),item.optString("title"),"実行結果を確認してください："+item.optString("state"),"inbox"));}}catch(Exception e){issues.put("受信箱");}try{JSONObject workspace=ConversationWorkspace.snapshot(c);JSONArray transfers=workspace.optJSONArray("transfers");for(int i=0;transfers!=null&&i<transfers.length();i++){JSONObject x=transfers.getJSONObject(i);if(x.optString("phase").matches("FAILED|PARTIAL|INTERRUPTED"))items.put(row("transfer",x.optString("batchId"),x.optString("kind").equals("photo")?"写真の保存確認":"録音の保存確認",TransferProgressPolicy.label(x)+(workspace.optBoolean("connected")?"":"（古い状態の可能性）"),"storage"));}File[] photos=RecorderPhotoStore.root(c).listFiles((d,n)->n.endsWith(".part"));if(photos!=null&&photos.length>0)items.put(row("storage","partial-photo","受信途中の写真",photos.length+"区間が残っています。保存照合で確認してください","storage"));}catch(Exception e){issues.put("保存状態");}try{JSONObject schedule=ScheduledTransfer.read(c);if(schedule.optString("state").matches("queue-failed|dispatch-unconfirmed|queued-unconfirmed|result-unconfirmed")||schedule.optString("remotePhase").matches("FAILED|PARTIAL|REJECTED|INTERRUPTED|EXPIRED"))items.put(row("reservation",schedule.optString("id"),"転送予約の結果",schedule.optString("reason"),"schedule"));}catch(Exception e){issues.put("転送予約");}try{JSONObject lease=MaintenanceLease.status(c);if(lease.optString("phase").matches("INTERRUPTED|FAILED"))items.put(row("maintenance","local-maintenance","保守処理の結果を確認",lease.optString("kind")+" / "+lease.optString("phase"),"maintenance"));}catch(Exception e){issues.put("保守処理の状態");}return new JSONObject().put("items",items).put("issues",issues).put("at",System.currentTimeMillis()).put("scope","端末内の直近処理・保留案件・タスク期限・記憶見直し・受信途中の写真・グラスから届いた転送結果。取得できない分類は未確認として表示。全写真・全音声の内容照合は保存確認画面で行ってください");}
 private AttentionHub(){}
}
